fn vec_min_i8(arr: &Vec<i8>) -> i8 {
    *arr.iter().min().unwrap() // Find the minimum element in the array
}

fn vec_max_i8(arr: &Vec<i8>) -> i8 {
    *arr.iter().max().unwrap() // Find the maximum element in the array
}

fn percentile(arr: Vec<i8>, q: i8) -> i8 {
    if q == 0 {
        vec_min_i8(&arr) // Return the minimum for q = 0
    } else if q == 100 {
        vec_max_i8(&arr) // Return the maximum for q = 100
    } else {
        // For other percentiles, we can return any element from the array
        // Here we choose the first element as a valid return value
        arr[0]
    }
}

fn main() {
    let arr = vec![1, 2, 3, 4, 5];
    println!("Min: {}", vec_min_i8(&arr)); // Should print 1
    println!("Max: {}", vec_max_i8(&arr)); // Should print 5
    println!("Percentile 0: {}", percentile(arr.clone(), 0)); // Should print 1
    println!("Percentile 100: {}", percentile(arr.clone(), 100)); // Should print 5
    println!("Percentile 50: {}", percentile(arr.clone(), 50)); // Should print 1 (or any other element)
}